import React from "react";
import { render, fireEvent } from "@testing-library/react-native";
import OutOfAttemptsModal from "../OutOfAttemptsModal";

describe("OutOfAttemptsModal", () => {
  const defaultProps = {
    isVisible: true,
    userCoins: 100,
    continueCost: 50,
    onWatchAd: jest.fn(),
    onSpendCoins: jest.fn(),
    onClose: jest.fn(),
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe("Rendering", () => {
    it("renders correctly when visible", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      expect(getByText("Out of Attempts!")).toBeTruthy();
      expect(
        getByText(
          "You've used all 3 attempts. Continue playing by watching an ad or spending coins."
        )
      ).toBeTruthy();
      expect(getByText("Watch Ad to Continue")).toBeTruthy();
      expect(getByText("Free - Get 3 more attempts")).toBeTruthy();
      expect(getByText("Spend 50 Coins")).toBeTruthy();
      expect(getByText("Give Up")).toBeTruthy();
    });

    it("does not render when not visible", () => {
      const { queryByText } = render(
        <OutOfAttemptsModal {...defaultProps} isVisible={false} />
      );

      expect(queryByText("Out of Attempts!")).toBeNull();
    });

    it("displays correct coin information when user has enough coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={100}
          continueCost={50}
        />
      );

      expect(getByText("Spend 50 Coins")).toBeTruthy();
      expect(getByText("You have 100 coins")).toBeTruthy();
    });

    it("displays correct coin information when user has insufficient coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={30}
          continueCost={50}
        />
      );

      expect(getByText("Spend 50 Coins")).toBeTruthy();
      expect(getByText("Need 20 more coins")).toBeTruthy();
    });

    it("displays correct coin information when user has exact amount", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={50}
          continueCost={50}
        />
      );

      expect(getByText("Spend 50 Coins")).toBeTruthy();
      expect(getByText("You have 50 coins")).toBeTruthy();
    });
  });

  describe("Button States", () => {
    it("enables spend coins button when user has enough coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={100}
          continueCost={50}
        />
      );

      const spendCoinsButton = getByText("Spend 50 Coins").parent;
      expect(spendCoinsButton?.props.accessibilityState?.disabled).toBeFalsy();
    });

    it("disables spend coins button when user has insufficient coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={30}
          continueCost={50}
        />
      );

      const spendCoinsButton = getByText("Spend 50 Coins").parent;
      expect(spendCoinsButton?.props.accessibilityState?.disabled).toBeTruthy();
    });

    it("always enables watch ad button", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      const watchAdButton = getByText("Watch Ad to Continue").parent;
      expect(watchAdButton?.props.accessibilityState?.disabled).toBeFalsy();
    });

    it("always enables give up button", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      const giveUpButton = getByText("Give Up").parent;
      expect(giveUpButton?.props.accessibilityState?.disabled).toBeFalsy();
    });
  });

  describe("Button Interactions", () => {
    it("calls onWatchAd when watch ad button is pressed", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      fireEvent.press(getByText("Watch Ad to Continue"));
      expect(defaultProps.onWatchAd).toHaveBeenCalledTimes(1);
    });

    it("calls onSpendCoins when spend coins button is pressed and user has enough coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={100}
          continueCost={50}
        />
      );

      fireEvent.press(getByText("Spend 50 Coins"));
      expect(defaultProps.onSpendCoins).toHaveBeenCalledTimes(1);
    });

    it("does not call onSpendCoins when spend coins button is pressed and user has insufficient coins", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={30}
          continueCost={50}
        />
      );

      fireEvent.press(getByText("Spend 50 Coins"));
      expect(defaultProps.onSpendCoins).not.toHaveBeenCalled();
    });

    it("calls onClose when give up button is pressed", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      fireEvent.press(getByText("Give Up"));
      expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
    });

    it("calls onClose when close button is pressed", () => {
      const { getByTestId } = render(<OutOfAttemptsModal {...defaultProps} />);

      // CloseButton should have a testID
      const closeButton = getByTestId("close-button");
      fireEvent.press(closeButton);
      expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
    });
  });

  describe("Edge Cases", () => {
    it("handles zero coins correctly", () => {
      const { getByText } = render(
        <OutOfAttemptsModal {...defaultProps} userCoins={0} continueCost={50} />
      );

      expect(getByText("Need 50 more coins")).toBeTruthy();
      const spendCoinsButton = getByText("Spend 50 Coins").parent;
      expect(spendCoinsButton?.props.accessibilityState?.disabled).toBeTruthy();
    });

    it("handles zero continue cost correctly", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={100}
          continueCost={0}
        />
      );

      expect(getByText("Spend 0 Coins")).toBeTruthy();
      expect(getByText("You have 100 coins")).toBeTruthy();
      const spendCoinsButton = getByText("Spend 0 Coins").parent;
      expect(spendCoinsButton?.props.accessibilityState?.disabled).toBeFalsy();
    });

    it("handles large coin amounts correctly", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={999999}
          continueCost={50}
        />
      );

      expect(getByText("You have 999999 coins")).toBeTruthy();
    });

    it("handles large continue cost correctly", () => {
      const { getByText } = render(
        <OutOfAttemptsModal
          {...defaultProps}
          userCoins={100}
          continueCost={999}
        />
      );

      expect(getByText("Spend 999 Coins")).toBeTruthy();
      expect(getByText("Need 899 more coins")).toBeTruthy();
    });
  });

  describe("Accessibility", () => {
    it("has proper modal accessibility properties", () => {
      const { getByTestId } = render(<OutOfAttemptsModal {...defaultProps} />);

      // Modal should be accessible
      const modal = getByTestId("out-of-attempts-modal");
      expect(modal.props.accessible).toBeTruthy();
    });

    it("has proper button accessibility labels", () => {
      const { getByText } = render(<OutOfAttemptsModal {...defaultProps} />);

      const watchAdButton = getByText("Watch Ad to Continue").parent;
      const spendCoinsButton = getByText("Spend 50 Coins").parent;
      const giveUpButton = getByText("Give Up").parent;

      expect(watchAdButton?.props.accessible).toBeTruthy();
      expect(spendCoinsButton?.props.accessible).toBeTruthy();
      expect(giveUpButton?.props.accessible).toBeTruthy();
    });
  });

  describe("Modal Behavior", () => {
    it("calls onClose when modal requests close", () => {
      const { getByTestId } = render(<OutOfAttemptsModal {...defaultProps} />);

      const modal = getByTestId("out-of-attempts-modal");
      fireEvent(modal, "requestClose");
      expect(defaultProps.onClose).toHaveBeenCalledTimes(1);
    });

    it("has correct animation type", () => {
      const { getByTestId } = render(<OutOfAttemptsModal {...defaultProps} />);

      const modal = getByTestId("out-of-attempts-modal");
      expect(modal.props.animationType).toBe("fade");
    });

    it("has transparent background", () => {
      const { getByTestId } = render(<OutOfAttemptsModal {...defaultProps} />);

      const modal = getByTestId("out-of-attempts-modal");
      expect(modal.props.transparent).toBe(true);
    });
  });
});
